// Renders docs/mcp-tools.json (generated by packages/roku-dev-studio-mcp/scripts/gen-docs.mjs)
// into the tool reference page. Pure client-side render — the JSON is the only source of truth,
// so this file never needs updating when a tool is added, changed, or removed.
(function () {
  var listEl = document.getElementById('tool-list');
  var leadEl = document.getElementById('tool-count-lead');
  var searchEl = document.getElementById('tool-search');
  var filtersEl = document.getElementById('tool-filters');
  var emptyEl = document.getElementById('tool-empty');
  var emptyQueryEl = document.getElementById('tool-empty-query');
  if (!listEl) return;

  function escapeHtml(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // Tool/property prose is authored as plain text with light Markdown (`code`, **bold**) — escape
  // first (backticks/asterisks pass through untouched), then promote the two markers actually
  // used in this codebase's descriptions. Not a general Markdown parser by design: no links,
  // lists, or headings are expected inline here.
  function renderInlineMarkdown(s) {
    return escapeHtml(s)
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  }

  // `type` is either a bare string or (e.g. a nullable field, `["object","null"]`) an array of
  // them — these two checks match either form so a nullable object/array still expands into rows
  // instead of silently falling back to a bare type label.
  function hasType(t, name) {
    return t === name || (Array.isArray(t) && t.indexOf(name) !== -1);
  }

  function describeType(schema) {
    if (!schema) return '—';
    if (schema.enum) return schema.enum.map(function (v) { return JSON.stringify(v); }).join(' | ');
    var t = schema.type;
    if (Array.isArray(t)) t = t.join(' | ');
    if (t === 'array') {
      var itemType = schema.items ? describeType(schema.items) : 'any';
      return 'array<' + itemType + '>';
    }
    return t || 'any';
  }

  // Recursively flattens `properties` into dotted-path rows (`result.data.compileErrors`,
  // `breakpoints[].filePath`, ...) instead of stopping at "object"/"array<object>" — a bare type
  // name told the reader nothing was there when the schema actually declares what's inside. Depth
  // is capped defensively (no schema in this codebase nests that deep; recursion also can't loop
  // forever since `children`-style self-references are deliberately left without a nested `items`
  // schema — see VARIABLE_PROPERTIES in tools.ts).
  var MAX_SCHEMA_DEPTH = 6;
  function collectSchemaRows(schema, prefix, depth, out) {
    if (!schema || typeof schema !== 'object' || depth > MAX_SCHEMA_DEPTH) return;
    var props = schema.properties && typeof schema.properties === 'object' ? schema.properties : null;
    if (!props) return;
    var required = Array.isArray(schema.required) ? schema.required : [];
    Object.keys(props).forEach(function (key) {
      var p = props[key] || {};
      var path = prefix + key;
      out.push({
        path: path,
        depth: depth,
        type: describeType(p),
        enumValues: Array.isArray(p.enum) ? p.enum : null,
        required: required.indexOf(key) !== -1,
        description: p.description || ''
      });
      if (hasType(p.type, 'object') && p.properties) {
        collectSchemaRows(p, path + '.', depth + 1, out);
      } else if (hasType(p.type, 'array') && p.items && hasType(p.items.type, 'object') && p.items.properties) {
        collectSchemaRows(p.items, path + '[].', depth + 1, out);
      }
    });
  }

  function schemaTable(schema, emptyMessage) {
    var rows = [];
    collectSchemaRows(schema, '', 0, rows);
    if (rows.length === 0) return '<p class="tool-schema-note">' + renderInlineMarkdown(emptyMessage) + '</p>';
    var rowsHtml = rows
      .map(function (row) {
        var indent = row.depth > 0 ? ' style="padding-left:' + row.depth * 1.25 + 'rem"' : '';
        var typeHtml = row.enumValues
          ? row.enumValues.map(function (v) { return '<code>' + escapeHtml(JSON.stringify(v)) + '</code>'; }).join(' | ')
          : escapeHtml(row.type);
        return (
          '<tr>' +
          '<td' + indent + '><code>' + escapeHtml(row.path) + '</code></td>' +
          '<td>' + typeHtml + '</td>' +
          '<td>' + (row.required
            ? '<span class="req-icon req-yes" title="Required" aria-label="Required">&#10003;</span>'
            : '<span class="req-icon req-no" title="Optional" aria-label="Optional">&#8211;</span>') + '</td>' +
          '<td>' + renderInlineMarkdown(row.description) + '</td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<table><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody>' +
      rowsHtml +
      '</tbody></table>'
    );
  }

  function annotationBadges(a) {
    if (!a) return '';
    var badges = [];
    if (a.readOnlyHint) badges.push('<span class="badge badge-cyan">Read-only</span>');
    else badges.push('<span class="badge badge-amber">Mutating</span>');
    if (a.destructiveHint) badges.push('<span class="badge badge-red">Destructive</span>');
    if (a.idempotentHint) badges.push('<span class="badge badge-purple">Idempotent</span>');
    return badges.join(' ');
  }

  // Display order comes from the generator (`categories` = the order TOOL_CATEGORY_GROUPS declares
  // in tools.ts, which mirrors the in-app "View MCP Tools" modal). Anything unrecognized is
  // appended alphabetically rather than dropped.
  function slug(s) { return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

  function groupByCategory(tools, order) {
    var byCategory = {};
    tools.forEach(function (t) {
      var key = t.category || 'Other';
      (byCategory[key] = byCategory[key] || []).push(t);
    });
    var known = order.filter(function (c) { return byCategory[c]; });
    var rest = Object.keys(byCategory)
      .filter(function (c) { return order.indexOf(c) === -1; })
      .sort();
    return known.concat(rest).map(function (category) {
      return { category: category, tools: byCategory[category] };
    });
  }

  // Tool.description is authored as a single string or an array of discrete points (see the
  // Tool type in tools.ts) — render points as a bullet list; a plain string stays one paragraph.
  function descriptionHtml(description) {
    if (Array.isArray(description)) {
      return '<ul class="tool-description-points">' + description.map(function (point) { return '<li>' + renderInlineMarkdown(point) + '</li>'; }).join('') + '</ul>';
    }
    return '<p>' + renderInlineMarkdown(description) + '</p>';
  }

  function descriptionSearchText(description) {
    return (Array.isArray(description) ? description.join(' ') : description || '').toLowerCase();
  }

  function toolCard(tool) {
    var titleText = tool.title ? escapeHtml(tool.title) : '';
    return (
      '<details class="tool-item" data-name="' + escapeHtml(tool.name.toLowerCase()) + '" data-desc="' +
      escapeHtml(descriptionSearchText(tool.description)) + '" data-readonly="' + (tool.annotations && tool.annotations.readOnlyHint ? '1' : '0') + '">' +
      '<summary><code>' + escapeHtml(tool.name) + '</code> <span class="tool-title">' + titleText + '</span>' +
      '<span class="tool-badges">' + annotationBadges(tool.annotations) + '</span></summary>' +
      '<div class="tool-item-body">' +
      descriptionHtml(tool.description) +
      '<h4>Input</h4>' +
      schemaTable(tool.inputSchema, 'No parameters.') +
      '<h4>Response</h4>' +
      (tool.outputSchema
        ? schemaTable(tool.outputSchema, 'Declared as a permissive object — see the raw schema below.')
        : '<p class="tool-schema-note">No declared response schema — this tool returns unstructured text/JSON content.</p>') +
      '<details class="tool-raw"><summary>Raw JSON schema</summary><pre><code>' +
      escapeHtml(JSON.stringify({ inputSchema: tool.inputSchema, outputSchema: tool.outputSchema }, null, 2)) +
      '</code></pre></details>' +
      '</div>' +
      '</details>'
    );
  }

  function applyFilter() {
    var query = (searchEl.value || '').trim().toLowerCase();
    var activeChip = filtersEl.querySelector('.chip.active');
    var mode = activeChip ? activeChip.dataset.filter : 'all';
    var visibleCount = 0;
    listEl.querySelectorAll('.tool-group').forEach(function (group) {
      var groupVisible = 0;
      group.querySelectorAll('.tool-item').forEach(function (item) {
        var matchesQuery = !query || item.dataset.name.indexOf(query) !== -1 || item.dataset.desc.indexOf(query) !== -1;
        var matchesMode = mode === 'all' || (mode === 'readonly' && item.dataset.readonly === '1') || (mode === 'mutating' && item.dataset.readonly === '0');
        var visible = matchesQuery && matchesMode;
        item.hidden = !visible;
        if (visible) groupVisible++;
      });
      group.hidden = groupVisible === 0;
      visibleCount += groupVisible;
    });
    emptyEl.hidden = visibleCount !== 0;
    if (emptyQueryEl) emptyQueryEl.textContent = query;
  }

  function renderChips() {
    var chips = [
      { key: 'all', label: 'All' },
      { key: 'readonly', label: 'Read-only' },
      { key: 'mutating', label: 'Mutating' }
    ];
    filtersEl.innerHTML = chips
      .map(function (c, i) {
        return '<button type="button" class="chip' + (i === 0 ? ' active' : '') + '" data-filter="' + c.key + '">' + c.label + '</button>';
      })
      .join('');
    filtersEl.querySelectorAll('.chip').forEach(function (chip) {
      chip.addEventListener('click', function () {
        filtersEl.querySelectorAll('.chip').forEach(function (c) { c.classList.remove('active'); });
        chip.classList.add('active');
        applyFilter();
      });
    });
  }

  fetch('mcp-tools.json')
    .then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(function (data) {
      leadEl.textContent =
        data.count + ' tools, reference documentation generated straight from the MCP Tools package.';
      listEl.innerHTML = groupByCategory(data.tools, data.categories || [])
        .map(function (group) {
          return (
            '<section class="tool-group" id="cat-' + slug(group.category) + '">' +
            '<h3 class="tool-group-title">' + escapeHtml(group.category) + ' <span class="tool-group-count">(' + group.tools.length + ')</span></h3>' +
            group.tools.map(toolCard).join('') +
            '</section>'
          );
        })
        .join('');
      renderChips();
      searchEl.addEventListener('input', applyFilter);
      applyFilter();
      // mcp.html's intro card links to #cat-<group>; the groups only exist after this render.
      if (location.hash) { var target = document.getElementById(location.hash.slice(1)); if (target) target.scrollIntoView(); }
    })
    .catch(function (err) {
      leadEl.textContent = 'Could not load the tool catalog (' + err.message + ').';
      listEl.innerHTML =
        '<p class="tool-schema-note">If you opened this file directly from disk, browsers block <code>fetch()</code> of local JSON over <code>file://</code> — serve the docs/ folder instead (e.g. <code>npx serve docs</code>), or view <a href="mcp-tools.json">mcp-tools.json</a> directly.</p>';
    });
})();
